import { BatchIdResponse, GetAllPostageBatchesResponse, GetPostageBatchBucketsResponse, GetPostageBatchResponse } from "../types/schema/stamps.js";
import { http } from "../utils/http.js";
import { mapPostageBatch } from "../utils/stamps.js";
const STAMPS_ENDPOINT = 'stamps';
/**
 * Raw HTTP calls for the `/stamps` endpoint.
 */
export async function createPostageBatch(requestOptions, amount, depth, label, gasPrice, immutableFlag) {
  const headers = {};
  if (gasPrice) {
    headers['gas-price'] = gasPrice;
  }
  if (immutableFlag !== undefined) {
    headers.immutable = String(immutableFlag);
  }
  const response = await http(requestOptions, {
    method: 'post',
    url: `${STAMPS_ENDPOINT}/${amount}/${depth}`,
    responseType: 'json',
    params: {
      label
    },
    headers
  });
  return BatchIdResponse.parse(response.data).batchID;
}
export async function updateLabel(requestOptions, id, label) {
  await http(requestOptions, {
    method: 'patch',
    url: `${STAMPS_ENDPOINT}/${id}`,
    responseType: 'json',
    data: {
      label
    }
  });
}
export async function topUpBatch(requestOptions, id, amount) {
  const response = await http(requestOptions, {
    method: 'patch',
    url: `${STAMPS_ENDPOINT}/topup/${id}/${amount}`,
    responseType: 'json'
  });
  return BatchIdResponse.parse(response.data).batchID;
}
export async function diluteBatch(requestOptions, id, depth) {
  const response = await http(requestOptions, {
    method: 'patch',
    url: `${STAMPS_ENDPOINT}/dilute/${id}/${depth}`,
    responseType: 'json'
  });
  return BatchIdResponse.parse(response.data).batchID;
}
export async function getPostageBatch(requestOptions, id, encryption, erasureCodeLevel) {
  const response = await http(requestOptions, {
    method: 'get',
    url: `${STAMPS_ENDPOINT}/${id}`,
    responseType: 'json'
  });
  return mapPostageBatch(GetPostageBatchResponse.parse(response.data), encryption, erasureCodeLevel);
}
export async function getPostageBatchBuckets(requestOptions, id) {
  const response = await http(requestOptions, {
    method: 'get',
    url: `${STAMPS_ENDPOINT}/${id}/buckets`,
    responseType: 'json'
  });
  return GetPostageBatchBucketsResponse.parse(response.data);
}
export async function getAllPostageBatches(requestOptions) {
  const response = await http(requestOptions, {
    method: 'get',
    url: STAMPS_ENDPOINT,
    responseType: 'json'
  });
  return GetAllPostageBatchesResponse.parse(response.data).stamps.map(x => mapPostageBatch(x));
}